import unittest
from candidate import fib4


class TestFib4BaseCases(unittest.TestCase):
    def test_fib4_zero_returns_zero(self):
        self.assertEqual(fib4(0), 0)

    def test_fib4_one_returns_zero(self):
        self.assertEqual(fib4(1), 0)

    def test_fib4_two_returns_two(self):
        self.assertEqual(fib4(2), 2)

    def test_fib4_three_returns_zero(self):
        self.assertEqual(fib4(3), 0)


class TestFib4RecursiveCases(unittest.TestCase):
    def test_fib4_four_returns_two(self):
        self.assertEqual(fib4(4), 2)

    def test_fib4_five_returns_four(self):
        self.assertEqual(fib4(5), 4)

    def test_fib4_six_returns_eight(self):
        self.assertEqual(fib4(6), 8)

    def test_fib4_seven_returns_fourteen(self):
        self.assertEqual(fib4(7), 14)

    def test_fib4_eight_returns_twentyeight(self):
        self.assertEqual(fib4(8), 28)

    def test_fib4_nine_returns_fiftyfour(self):
        self.assertEqual(fib4(9), 54)

    def test_fib4_ten_returns_onehundredfour(self):
        self.assertEqual(fib4(10), 104)

    def test_fib4_fifteen_returns_fifteen_hundred_something(self):
        expected = self._compute_fib4(15)
        self.assertEqual(fib4(15), expected)

    def test_fib4_twenty_returns_correct_value(self):
        expected = self._compute_fib4(20)
        self.assertEqual(fib4(20), expected)

    def _compute_fib4(self, n):
        if n == 0:
            return 0
        if n == 1:
            return 0
        if n == 2:
            return 2
        if n == 3:
            return 0
        a, b, c, d = 0, 0, 2, 0
        for _ in range(4, n + 1):
            a, b, c, d = b, c, d, a + b + c + d
        return d


class TestFib4EdgeCases(unittest.TestCase):
    def test_fib4_large_n_computes_correctly(self):
        n = 50
        expected = self._compute_fib4(n)
        self.assertEqual(fib4(n), expected)

    def test_fib4_returns_int_type(self):
        self.assertIsInstance(fib4(0), int)
        self.assertIsInstance(fib4(5), int)
        self.assertIsInstance(fib4(20), int)

    def test_fib4_sequence_is_monotonically_increasing_after_three(self):
        for i in range(4, 15):
            self.assertGreater(fib4(i), fib4(i - 1))


class TestFib4ErrorHandling(unittest.TestCase):
    def test_fib4_negative_one_returns_results_negative_one(self):
        self.assertEqual(fib4(-1), 0)

    def test_fib4_negative_five_raises_index_error(self):
        with self.assertRaises(IndexError):
            fib4(-5)

    def test_fib4_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            fib4(None)

    def test_fib4_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            fib4("5")

    def test_fib4_float_raises_type_error(self):
        with self.assertRaises(TypeError):
            fib4(5.5)

    def test_fib4_zero_float_raises_type_error(self):
        with self.assertRaises(TypeError):
            fib4(0.0)

    def test_fib4_list_raises_type_error(self):
        with self.assertRaises(TypeError):
            fib4([1, 2, 3])


class TestFib4Consistency(unittest.TestCase):
    def test_fib4_repeated_calls_return_same_result(self):
        for i in range(0, 12):
            first = fib4(i)
            second = fib4(i)
            self.assertEqual(first, second)

    def test_fib4_matches_docstring_examples(self):
        self.assertEqual(fib4(5), 4)
        self.assertEqual(fib4(6), 8)
        self.assertEqual(fib4(7), 14)


if __name__ == '__main__':
    unittest.main()
